import{_ as t,o as a,c as r,a2 as i}from"./chunks/framework.BXzK3EA4.js";const g=JSON.parse('{"title":"Scheduling Policies","description":"","frontmatter":{},"headers":[],"relativePath":"concepts/scheduling-policies.md","filePath":"concepts/scheduling-policies.md","lastUpdated":null}'),n={name:"concepts/scheduling-policies.md"};function o(d,e,s,l,h,c){return a(),r("div",null,[...e[0]||(e[0]=[i('<h1 id="scheduling-policies" tabindex="-1">Scheduling Policies <a class="header-anchor" href="#scheduling-policies" aria-label="Permalink to &quot;Scheduling Policies&quot;">​</a></h1><p>Seven policies ship with ASTRA. Six are honest reference baselines; SmartScan is the proposed hybrid.</p><h2 id="policy-comparison" tabindex="-1">Policy comparison <a class="header-anchor" href="#policy-comparison" aria-label="Permalink to &quot;Policy comparison&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Name</th><th>Type</th><th>Learns?</th><th>Coverage</th><th>Reward</th><th>Prediction</th></tr></thead><tbody><tr><td><strong>Sequential sweep</strong></td><td>Open loop</td><td>No</td><td>High</td><td>Low</td><td>None</td></tr><tr><td><strong>Random scan</strong></td><td>Open loop</td><td>No</td><td>High</td><td>Low</td><td>None</td></tr><tr><td><strong>Priority sweep</strong></td><td>Open loop</td><td>No</td><td>Medium</td><td>Low</td><td>None</td></tr><tr><td><strong>UCB bandit</strong></td><td>Adaptive</td><td>Yes (exploit only)</td><td><strong>Low</strong></td><td><strong>High</strong></td><td>High</td></tr><tr><td><strong>Linear Q-learning</strong></td><td>RL</td><td>Yes</td><td>High</td><td>Medium</td><td><strong>Low</strong></td></tr><tr><td><strong>Deep Q-network</strong></td><td>Deep RL</td><td>Yes</td><td>Medium</td><td>Medium</td><td>Medium</td></tr><tr><td><strong>SmartScan</strong></td><td>Hybrid</td><td>Yes</td><td><strong>High</strong></td><td><strong>High</strong></td><td><strong>High</strong></td></tr></tbody></table><h2 id="detailed-descriptions" tabindex="-1">Detailed descriptions <a class="header-anchor" href="#detailed-descriptions" aria-label="Permalink to &quot;Detailed descriptions&quot;">​</a></h2><h3 id="sequential-sweep" tabindex="-1">Sequential sweep <a class="header-anchor" href="#sequential-sweep" aria-label="Permalink to &quot;Sequential sweep&quot;">​</a></h3><p>Visits every band in a fixed cyclic order. The simplest approach — no learning, no adaptation. Serves as the conventional baseline.</p><h3 id="random-scan" tabindex="-1">Random scan <a class="header-anchor" href="#random-scan" aria-label="Permalink to &quot;Random scan&quot;">​</a></h3><p>Selects bands uniformly at random. Covers the spectrum well (by chance) but wastes time on empty bands with no intelligence.</p><h3 id="priority-sweep" tabindex="-1">Priority sweep <a class="header-anchor" href="#priority-sweep" aria-label="Permalink to &quot;Priority sweep&quot;">​</a></h3><p>Uses pre-programmed intelligence to visit high-priority bands first. Requires prior knowledge that may not be available in practice.</p><h3 id="ucb-bandit-upper-confidence-bound" tabindex="-1">UCB bandit (Upper Confidence Bound) <a class="header-anchor" href="#ucb-bandit-upper-confidence-bound" aria-label="Permalink to &quot;UCB bandit (Upper Confidence Bound)&quot;">​</a></h3><p>Multi-armed bandit approach: exploits the highest-reward band while occasionally exploring others. Converges on the richest band but <strong>misses 46% of threats</strong> — the classic exploit trap.</p><h3 id="linear-q-learning" tabindex="-1">Linear Q-learning <a class="header-anchor" href="#linear-q-learning" aria-label="Permalink to &quot;Linear Q-learning&quot;">​</a></h3><p>Tabular reinforcement learning with hand-crafted features. Learns value estimates over bands but predicts presence at near-chance level on this sparse-reward task.</p><h3 id="deep-q-network-dqn" tabindex="-1">Deep Q-network (DQN) <a class="header-anchor" href="#deep-q-network-dqn" aria-label="Permalink to &quot;Deep Q-network (DQN)&quot;">​</a></h3><p>Neural network function approximation with experience replay and target network. More capacity than linear Q-learning but suffers from overfitting on the sparse, high-dimensional EW task. Declines on held-out greedy evaluation.</p><h3 id="smartscan-proposed" tabindex="-1">SmartScan (proposed) <a class="header-anchor" href="#smartscan-proposed" aria-label="Permalink to &quot;SmartScan (proposed)&quot;">​</a></h3><p>Hybrid scheduler multiplexing five behaviours (recon, phase-lock pursuit, predict-and-probe, burst characterisation, value-weighted rotation) based on learned confidence. The only policy passing all three KPP gates simultaneously.</p><h2 id="why-ucb-fails-despite-high-reward" tabindex="-1">Why UCB fails despite high reward <a class="header-anchor" href="#why-ucb-fails-despite-high-reward" aria-label="Permalink to &quot;Why UCB fails despite high reward&quot;">​</a></h2><p>The UCB bandit achieves the highest raw reward because it camps on the single most productive band. But it <strong>misses 46% of all threats</strong> — it never sweeps for new or rare emitters. In a defence context, missing nearly half the threats is unacceptable regardless of reward.</p><h2 id="why-q-learning-fails-despite-coverage" tabindex="-1">Why Q-learning fails despite coverage <a class="header-anchor" href="#why-q-learning-fails-despite-coverage" aria-label="Permalink to &quot;Why Q-learning fails despite coverage&quot;">​</a></h2><p>Linear Q-learning covers most threats (89.6%) but its prediction accuracy is only 19% — barely above chance. It learns to visit threatening bands but cannot predict when they will transmit again.</p>',23)])])}const u=t(n,[["render",o]]);export{g as __pageData,u as default};
